// src/components/Navbar.js
import React from 'react';

const Navbar = () => {
  return (
    <nav
      className="w-full max-w-[1280px] mx-auto flex items-center justify-between pt-2 pb-2 px-0 
                 text-white text-center antialiased box-border border-b-2 border-white 
                 shadow-md"
      style={{
        background: `linear-gradient(
          to right,
          #00C270 0%,
          #00C270 25%,
          #00367E 50%,
          #00367E 75%,
          #00367E 100%
        )`
      }}
    >
      <div className="ml-4">
        <h2 className="text-xl font-bold">Actuary List</h2>
      </div>
      <ul className="flex gap-8 mr-4 list-none">
        <li><a href="#about" className="text-white font-bold hover:text-[#f0a500]">About</a></li>
        <li><a href="#blog" className="text-white font-bold hover:text-[#f0a500]">Blog</a></li>
        <li><a href="#jobPost" className="text-white font-bold hover:text-[#f0a500]">Post A Job</a></li>
        <li><a href="#freejobalerts" className="text-white font-bold hover:text-[#f0a500]">Get Free Job Alerts</a></li>
      </ul>
    </nav>
  );
};

export default Navbar;
